from importlib import import_module

# As in Pydantic, the names are imported when they are first read.
_dynamic_imports = {
    "BaseModel": ".main",
    "field_validator": ".functional_validators",
    "model_validator": ".functional_validators",
    "field_serializer": ".functional_serializers",
    "model_serializer": ".functional_serializers",
    "computed_field": ".fields",
    "validator": ".deprecated.class_validators",
    "root_validator": ".deprecated.class_validators",
}


def __getattr__(name):
    module = import_module(_dynamic_imports[name], __spec__.parent)
    return getattr(module, name)
